using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

namespace BuildingBlocks.Observability;

/// <summary>
/// API documentation for every service.
///
///   OpenAPI  = a JSON description of the API (endpoints, parameters, models).
///              Generated by Microsoft.AspNetCore.OpenApi at /openapi/v1.json
///   Swagger UI = a web page that reads that JSON and lets you click "Try it out".
///
/// In Docker the services are private, so the main Swagger UI lives at the GATEWAY
/// (http://localhost:5000/swagger) and shows all services in a dropdown.
/// Each service also serves its own /swagger page (useful with `dotnet run`).
/// </summary>
public static class OpenApiExtensions
{
    public static IServiceCollection AddServiceOpenApi(this IServiceCollection services, string serviceName)
        => services.AddOpenApi(options => options.AddDocumentTransformer((document, _, _) =>
        {
            document.Info.Title = serviceName;

            // By default the document lists the URL it was served from (e.g. http://product-service:8080).
            // Your browser can't reach that inside Docker. With NO servers listed, Swagger UI sends
            // "Try it out" requests to the host the page came from - the gateway - which routes them.
            document.Servers?.Clear();
            return Task.CompletedTask;
        }));

    public static WebApplication MapServiceOpenApi(this WebApplication app, string serviceName)
    {
        app.MapOpenApi(); // GET /openapi/v1.json
        app.UseSwaggerUI(options =>
        {
            options.SwaggerEndpoint("/openapi/v1.json", serviceName);
            options.RoutePrefix = "swagger"; // GET /swagger
        });
        return app;
    }
}
